// SubmitRescale Changes the size and scale of a 2D image.
//
//   - stream: in The stream where the operation will be queued in. + Must not be NULL. + Stream must have enabled the backends that will execute the algorithm
//   - backend: in VPI backend that will execute the algorithm. + Valid values: - VPI_BACKEND_CPU - VPI_BACKEND_CUDA - VPI_BACKEND_VIC
//   - input: in Input image to be rescaled. + Must not be NULL. + Image must have enabled the backends that will execute the algorithm. + Dimensions must be >= 1x1. On VIC, valid range is >= 16x16 and <= 16384x16384. + On VIC, when using YUV formats with chroma-subsampling of 4:2:0, 4:2:2 or 4:2:2R, the image dimensions must be even. + Supported image formats are: | Format | CPU | CUDA | VIC | |------------------------------------|:---:|:----:|:---:| | VPI_IMAGE_FORMAT_U8 | * | * | | | VPI_IMAGE_FORMAT_U16 | * | * | | | VPI_IMAGE_FORMAT_S8 | * | * | | | VPI_IMAGE_FORMAT_S16 | * | * | | | VPI_IMAGE_FORMAT_F32 | * | * | | | VPI_IMAGE_FORMAT_Y8 | * | * | * | | VPI_IMAGE_FORMAT_Y8_ER | * | * | * | | VPI_IMAGE_FORMAT_Y8_BL | | | * | | VPI_IMAGE_FORMAT_Y8_ER_BL | | | * | | VPI_IMAGE_FORMAT_Y8_BL16 | | | * | | VPI_IMAGE_FORMAT_Y8_ER_BL16 | | | * | | VPI_IMAGE_FORMAT_Y16 | * | * | * | | VPI_IMAGE_FORMAT_Y16_ER | * | * | * | | VPI_IMAGE_FORMAT_Y16_BL | | | * | | VPI_IMAGE_FORMAT_Y16_ER_BL | | | * | | VPI_IMAGE_FORMAT_Y16_BL16 | | | * | | VPI_IMAGE_FORMAT_Y16_ER_BL16 | | | * | | VPI_IMAGE_FORMAT_RGB8 | * | * | | | VPI_IMAGE_FORMAT_BGR8 | * | * | | | VPI_IMAGE_FORMAT_RGBA8 | * | * | * | | VPI_IMAGE_FORMAT_BGRA8 | * | * | * | | VPI_IMAGE_FORMAT_RGB8p | * | * | | | VPI_IMAGE_FORMAT_BGR8p | * | * | | | VPI_IMAGE_FORMAT_RGBA8p | * | * | | | VPI_IMAGE_FORMAT_BGRA8p | * | * | | | VPI_IMAGE_FORMAT_NV12 | * | * | * | | VPI_IMAGE_FORMAT_NV12_ER | * | * | * | | VPI_IMAGE_FORMAT_NV12_BL | | | * | | VPI_IMAGE_FORMAT_NV12_ER_BL | | | * | | VPI_IMAGE_FORMAT_NV12_BL16 | | | * | | VPI_IMAGE_FORMAT_NV12_ER_BL16 | | | * | | VPI_IMAGE_FORMAT_NV24 | * | * | * | | VPI_IMAGE_FORMAT_NV24_ER | * | * | * | | VPI_IMAGE_FORMAT_NV24_BL | | | * | | VPI_IMAGE_FORMAT_NV24_ER_BL | | | * | | VPI_IMAGE_FORMAT_NV24_BL16 | | | * | | VPI_IMAGE_FORMAT_NV24_ER_BL16 | | | * | | VPI_IMAGE_FORMAT_UYVY | | | * | | VPI_IMAGE_FORMAT_UYVY_ER | | | * | | VPI_IMAGE_FORMAT_UYVY_BL | | | * | | VPI_IMAGE_FORMAT_UYVY_ER_BL | | | * | | VPI_IMAGE_FORMAT_UYVY_BL16 | | | * | | VPI_IMAGE_FORMAT_UYVY_ER_BL16 | | | * | | VPI_IMAGE_FORMAT_YUYV | | | * | | VPI_IMAGE_FORMAT_YUYV_ER | | | * | | VPI_IMAGE_FORMAT_YUYV_BL | | | * | | VPI_IMAGE_FORMAT_YUYV_ER_BL | | | * | | VPI_IMAGE_FORMAT_YUYV_BL16 | | | * | | VPI_IMAGE_FORMAT_YUYV_ER_BL16 | | | * |
//   - output: out Output image with the desired resulting dimensions. + Must not be NULL. + Image must have enabled the backends that will execute the algorithm. + Dimensions must be >= 1x1. On VIC, valid range is >= 16x16 and <= 16384x16384. + On VIC, when using YUV formats with chroma-subsampling of 4:2:0, 4:2:2 or 4:2:2R, the image dimensions must be even. + On VIC, scale factor (output/input) must be between 1/16.0f and 16.0f. + On VIC, input and output formats can be different. Accepted formats are the same as input, provided that the following constraints are met: - No bit depth conversion is allowed, i.e., Y8 to Y16, Y16 to NV12, etc. - No conversion from/to Y16_ER, except when only changing layout. Example: Y16_ER_BL to Y16_ER is allowed, but Y16_ER_BL to Y16 or Y16_BL isn't. + On other backends, input and output formats must be the same
//   - interpolationType: in Interpolation method to be used. + Valid values: - [InterpNearest] - [InterpLinear] (VIC only supports this one) - [InterpCatmullRom]
//   - border: in Border extension to be used when sampling pixels outside the image border. + The accepted border extensions are: - [BorderZero] - [BorderClamp] (VIC only supports this one)
//   - flags: in Control flags. + Valid values are a combination of one or more of the following flags: - 0: default, negation of all other flags. - VPI_PRECISE : precise, but potentially slower implementation
//
// Returns:
//   - #VPI_ERROR_INVALID_ARGUMENT: stream is NULL.
//   - #VPI_ERROR_INVALID_ARGUMENT: input or output are NULL.
//   - #VPI_ERROR_INVALID_ARGUMENT: input or output dimensions are outside valid range.
//   - #VPI_ERROR_INVALID_ARGUMENT: flags has some unsupported flag(s).
//   - #VPI_ERROR_INVALID_ARGUMENT: border not supported.
//   - #VPI_ERROR_INVALID_ARGUMENT: interpolationType not supported.
//   - #VPI_ERROR_INVALID_ARGUMENT: backend is invalid or unknown.
//   - #VPI_ERROR_INVALID_ARGUMENT: input and output formats are not compatible.
//   - #VPI_ERROR_INVALID_IMAGE_FORMAT: input or output format not supported.
//   - #VPI_ERROR_NOT_IMPLEMENTED: Rescale algorithm is not supported by given backend.
//   - #VPI_ERROR_INVALID_OPERATION: Backend hardware not available.
//   - #VPI_ERROR_INVALID_OPERATION: The needed backends aren't enabled in stream, input or output.
//   - #VPI_SUCCESS: Operation executed successfully.
//
// Wraps vpiSubmitRescale.
func SubmitRescale(stream Stream, backend Backend, input Image, output Image, interpolationType InterpolationType, border BorderExtension, flags uint64) error {
	if err := checkLibSym("vpiSubmitRescale"); err != nil {
		return err
	}
	return toError(fnSubmitRescale(stream, backend, input, output, interpolationType, border, flags))
}
